    this.input = this.shadowRoot.querySelector('input');
    this.errorMessage = this.shadowRoot.querySelector('.error');

    // Attach internals to make the custom element form-associated
    this.internals = this.attachInternals();

    // Set the formAssociated property to true
    this.formAssociated = true;

    // Initialize the input element with the current attributes
    this.updateInputAttributes();
  }

  // Lifecycle method that runs when the element is added to the DOM
  connectedCallback() {
    // Ensure the input element is updated with the current attributes
    this.updateInputAttributes();
  }

  // Lifecycle method that runs when an observed attribute changes
  attributeChangedCallback(name, oldValue, newValue) {
    // Update the input element with the new attribute value
    this.updateInputAttributes();
  }

  // Method to update the input element with the current attributes
  updateInputAttributes() {
    if (this.input) {
      this.input.value = this.getAttribute('value') || '';
      this.input.disabled = this.hasAttribute('disabled');
      this.input.required = this.hasAttribute('required');
      this.input.setAttribute('list', this.getAttribute('list') || '');
    }
  }

  // Getter and setter for the value property
  get value() {
    return this.input.value;
  }

  set value(val) {
    this.input.value = val;
    this.setAttribute('value', val);
  }

  // Getter and setter for the disabled property
  get disabled() {
    return this.input.disabled;
  }

  set disabled(val) {
    this.input.disabled = val;
    if (val) {
      this.setAttribute('disabled', '');
    } else {
      this.removeAttribute('disabled');
    }
  }

  // Getter and setter for the required property
  get required() {
    return this.input.required;
  }

  set required(val) {
    this.input.required = val;
    if (val) {
      this.setAttribute('required', '');
    } else {
      this.removeAttribute('required');
    }
  }

  // Getter and setter for the list property
  get list() {
    return this.input.getAttribute('list');
  }

  set list(val) {
    this.input.setAttribute('list', val);
