    Key NVARCHAR(255) NOT NULL UNIQUE,
    Value NVARCHAR(MAX) NOT NULL
);
```

2. **Create a model class in your ASP.NET Core project to represent the AppSettings table:**

```csharp
public class AppSetting
{
    public int Id { get; set; }
    public string Key { get; set; }
    public string Value { get; set; }
}
```

3. **Create a DbContext class to work with the AppSettings table:**

```csharp
public class AppSettingsDbContext : DbContext
{
    public AppSettingsDbContext(DbContextOptions<AppSettingsDbContext> options)
        : base(options)
    {
    }

    public DbSet<AppSetting> AppSettings { get; set; }
}
```

4. **Register the DbContext in your Startup.cs:**

```csharp
public void ConfigureServices(IServiceCollection services)
{
    // ...
    services.AddDbContext<AppSettingsDbContext>(options =>
        options.UseSqlServer(Configuration.GetConnectionString("AppSettingsConnection")));
    // ...
}
```

5. **Create a service to read and update application settings:**

```csharp
public interface IAppSettingsService
{
    string GetSetting(string key);
    void UpdateSetting(string key, string value);
}

public class AppSettingsService : IAppSettingsService
{
    private readonly AppSettingsDbContext _context;

    public AppSettingsService(AppSettingsDbContext context)
    {
        _context = context;
    }

    public string GetSetting(string key)
    {
        var setting = _context.AppSettings.FirstOrDefault(s => s.Key == key);
        return setting?.Value ?? string.Empty;
    }

    public void UpdateSetting(string key, string value)
    {
        var setting = _context.AppSettings.FirstOrDefault(s => s.Key == key);

        if (setting == null)
        {
            _context.AppSettings.Add(new AppSetting { Key = key, Value = value });
        }
        else
        {
            setting.Value = value;
        }

        _context.SaveChanges();
    }
}
```

6. **Register the IAppSettingsService in your Startup.cs:**

```csharp
public void ConfigureServices(IServiceCollection services)
{
    // ...
    services.AddScoped<IAppSettingsService, AppSettingsService>();
    // ...
}
```

7. **Use the IAppSettingsService in your API controllers to read and update application settings:**

```csharp
[ApiController]
[Route("[controller]")]
public class SettingsController : ControllerBase
{
