        <input type="email" name="email" placeholder="Customer Email" required>
        <button type="submit">Add Customer</button>
    </form>
</body>
</html>
```

### Step 6: Update `WebSecurityConfigurerAdapter`

Configure Spring Security to manage user authentication and authorization.

```java
@Override
protected void configure(HttpSecurity http) throws Exception {
    http
        .authorizeRequests()
            .antMatchers("/api/customers/**").authenticated()
            .and()
        .formLogin()
            .loginPage("/login")
            .permitAll()
            .and()
